#define _GNU_SOURCE
#include <errno.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

extern char **environ;
_Atomic int opsforge_shared_value;
struct message { pid_t pid; pid_t ppid; int value; };
struct context { _Atomic int *value; int fd; };

static int transfer(int fd, void *data, size_t length, int writing) {
    size_t done = 0;
    while (done < length) {
        ssize_t count = writing ? write(fd, (char *)data + done, length - done)
                                : read(fd, (char *)data + done, length - done);
        if (count < 0 && errno == EINTR) continue;
        if (count <= 0) return -1;
        done += (size_t)count;
    }
    return 0;
}

static int clone_child(void *argument) {
    struct context *context = argument;
    atomic_fetch_add(context->value, 17);
    struct message message = {getpid(), getppid(), atomic_load(context->value)};
    if (transfer(context->fd, &message, sizeof(message), 1)) return 120;
    return 31;
}

static int waited(pid_t child) {
    int status;
    while (waitpid(child, &status, 0) < 0) {
        if (errno != EINTR) return -1;
    }
    return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
}

int main(int argc, char **argv) {
    if (argc != 4) return 2;
    const char *digits = argv[3];
    if (*digits == '+' || *digits == '-') digits++;
    if (!*digits) return 2;
    for (; *digits; digits++) {
        if (*digits < '0' || *digits > '9') return 2;
    }
    char *end = NULL;
    long initial = strtol(argv[3], &end, 10);
    if (!argv[3][0] || !end || *end || initial < -1000 || initial > 1000) return 2;
    atomic_store(&opsforge_shared_value, (int)initial);
    const char *mode = argv[1];
    char *helper = argv[2];
    if (!strcmp(mode, "exec")) {
        char *child_argv[] = {helper, "exec", NULL};
        execve(helper, child_argv, environ);
        return 127;
    }
    if (!strcmp(mode, "vfork")) {
        char *child_argv[] = {helper, "vfork", NULL};
        pid_t child = fork();
        if (child == 0) {
            execve(helper, child_argv, environ);
            _exit(127);
        }
        if (child < 0) return 2;
        int code = waited(child);
        printf("{\"mode\":\"vfork\",\"pid\":%ld,\"child\":%ld,\"waited_exit\":%d}\n",
               (long)getpid(), (long)child, code);
        return code == 29 ? 0 : 2;
    }
    if (!strcmp(mode, "fork") || !strcmp(mode, "clone")) {
        int descriptors[2];
        if (pipe(descriptors)) return 2;
        pid_t child;
        void *stack = NULL;
        struct context context = {&opsforge_shared_value, descriptors[1]};
        if (!strcmp(mode, "fork")) {
            child = fork();
            if (child == 0) {
                close(descriptors[0]);
                atomic_fetch_add(&opsforge_shared_value, 17);
                struct message message = {getpid(), getppid(), atomic_load(&opsforge_shared_value)};
                if (transfer(descriptors[1], &message, sizeof(message), 1)) _exit(120);
                _exit(23);
            }
        } else {
            size_t size = 1024 * 1024;
            stack = malloc(size);
            if (!stack) return 2;
            child = clone(clone_child, (char *)stack + size, CLONE_VM | SIGCHLD, &context);
        }
        if (child < 0) return 2;
        close(descriptors[1]);
        struct message message;
        int transferred = transfer(descriptors[0], &message, sizeof(message), 0);
        close(descriptors[0]);
        int code = waited(child);
        free(stack);
        if (transferred) return 2;
        printf("{\"mode\":\"%s\",\"pid\":%ld,\"child\":%ld,\"child_ppid\":%ld,"
               "\"parent_value\":%d,\"child_value\":%d,\"waited_exit\":%d}\n",
               mode, (long)getpid(), (long)message.pid, (long)message.ppid,
               atomic_load(&opsforge_shared_value), message.value, code);
        return 0;
    }
    return 2;
}

